const query  = $input.first()?.json?.query ?? {};
const jobId  = (query.jobId ?? '').trim();
if (!jobId) return [{ json: { status:'error', message:'jobId obrigatório' } }];
const store  = $getWorkflowStaticData('global');
const result = store[jobId];
if (!result) return [{ json: { status:'processing' } }];
delete store[jobId];
const r = typeof result === 'object' ? result : JSON.parse(result);
return [{ json: { status:'done', result: r } }];

const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const message = (body.message ?? '').trim();
const history = Array.isArray(body.history) ? body.history : [];
const analysisContext = body.analysisContext ?? null;
const jobId = (body.jobId ?? '').trim();
const userEmail = (body.userEmail ?? '').trim();
const gaToken = (body.gaToken ?? '').trim();
if (!message) throw new Error('Mensagem vazia.');
if (!jobId)   throw new Error('jobId obrigatório.');
return [{ json: { message, history, analysisContext, jobId, userEmail, gaToken, needsAnalysis: analysisContext === null } }];

const data = $('Parse Request').first()?.json ?? {};
const msg = data.message ?? '';
const urlMatch = msg.match(/https?:\/\/[^\s,;!?]+/);
if (!urlMatch) throw new Error('URL não encontrada. Exemplo: https://centauro.com.br tênis de corrida');
const url = urlMatch[0].replace(/[.,;!?]+$/, '').trim();
const topic = msg.replace(url,'').replace(/\b(analise|sobre|o site|a url|verifique|quero analisar)\b/gi,' ').replace(/\s+/g,' ').trim();
if (!topic) throw new Error('Informe o tópico após a URL.');
return [{ json: { url, topic, userEmail: data.userEmail ?? '' } }];

const psi = $input.first()?.json ?? {};
const lhr = psi.lighthouseResult ?? {};
const le  = psi.loadingExperience ?? {};
const aud = lhr.audits ?? {};
const met = le.metrics ?? {};
const scoreRaw = lhr.categories?.performance?.score;
return [{ json: {
  performance_score: scoreRaw != null ? Math.round(scoreRaw * 100) : null,
  fcp:  aud['first-contentful-paint']?.displayValue   ?? null,
  lcp:  aud['largest-contentful-paint']?.displayValue ?? null,
  tbt:  aud['total-blocking-time']?.displayValue      ?? null,
  cls:  aud['cumulative-layout-shift']?.displayValue  ?? null,
  si:   aud['speed-index']?.displayValue              ?? null,
  fcp_field: met.FIRST_CONTENTFUL_PAINT_MS?.category        ?? null,
  lcp_field: met.LARGEST_CONTENTFUL_PAINT_MS?.category      ?? null,
  inp_field: met.INTERACTION_TO_NEXT_PAINT?.category        ?? null,
  cls_field: met.CUMULATIVE_LAYOUT_SHIFT_SCORE?.category    ?? null,
  overall:   le.overall_category ?? null
}}];

const fanout    = $('Query Fan-out v2').first()?.json ?? {};
const geo       = $('Prompt Mapper GEO').first()?.json ?? {};
const onPage    = $('On-Page SEO Audit').first()?.json ?? {};
const psi       = $('Parse PSI').first()?.json ?? {};
const corepulse = $('Parse CorePulse').first()?.json ?? {};
const params    = $('Extrair URL e Tópico').first()?.json ?? {};

const context = {
  url_analisada: params.url,
  topico: params.topic,
  query_fanout: {
    fanout_queries:   fanout.fanout_queries   ?? {},
    cited_sources:    fanout.cited_sources    ?? {},
    source_diversity: fanout.source_diversity ?? {},
    seo_summary:      fanout.seo_summary      ?? {}
  },
  geo_mapping: {
    summary:       geo.summary ?? '',
    total_prompts: geo.total   ?? 0,
    prompts:       (geo.prompts ?? []).slice(0, 10)
  },
  on_page_audit: onPage,
  cwv_data: {
    psi: {
      fonte: 'PageSpeed Insights API (lab + campo CrUX)',
      performance_score: psi.performance_score,
      metricas_lab: { fcp: psi.fcp, lcp: psi.lcp, tbt: psi.tbt, cls: psi.cls, si: psi.si },
      campo_crux:   { fcp: psi.fcp_field, lcp: psi.lcp_field, inp: psi.inp_field, cls: psi.cls_field, overall: psi.overall }
    },
    corepulse: {
      fonte: 'CorePulse Analyzer (síncrono, sem disparo de e-mail)',
      status:  corepulse.corepulse_status,
      score:   corepulse.corepulse_score,
      lcp:     corepulse.corepulse_lcp,
      fcp:     corepulse.corepulse_fcp,
      cls:     corepulse.corepulse_cls,
      inp:     corepulse.corepulse_inp,
      tbt:     corepulse.corepulse_tbt,
      grade:   corepulse.corepulse_grade,
      summary: corepulse.corepulse_summary
    }
  }
};
return [{ json: { correlationContext: JSON.stringify(context, null, 2) } }];

const item = $input.first()?.json ?? {};
let raw = item.output ?? item.text ?? item.content ?? item.message ?? '';
if (typeof raw === 'object' && raw !== null && (raw.sumario || raw.correlacoes)) {
  raw = JSON.stringify(raw);
}
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim();

let analysisData = null;
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s !== -1 && e > s) {
  try { analysisData = JSON.parse(raw.slice(s, e + 1)); } catch(_) {}
}
if (!analysisData) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { analysisData = JSON.parse(m[0]); } catch(_) {} }
}

if (
  !analysisData ||
  typeof analysisData !== 'object' ||
  !analysisData.sumario ||
  !Array.isArray(analysisData.sumario?.insights) ||
  analysisData.sumario.insights.length === 0
) {
  analysisData = {
    sumario: {
      insights: [
        '⚠️ Parsing falhou. Campos: ' + Object.keys(item).join(', '),
        'Output (2000): ' + raw.slice(0, 2000)
      ],
      nivel_impacto: 'Indeterminado'
    },
    correlacoes: [], gaps_oportunidades: [], plano_acao: [], proximos_passos: []
  };
}

const params    = $('Extrair URL e Tópico').first()?.json ?? {};
const psi       = $('Parse PSI').first()?.json ?? {};
const corepulse = $('Parse CorePulse').first()?.json ?? {};

const userEmail = (params.userEmail ?? '').trim();
const cpHasMetrics =
  corepulse.corepulse_score != null ||
  corepulse.corepulse_lcp   != null ||
  corepulse.corepulse_fcp   != null ||
  corepulse.corepulse_cls   != null ||
  corepulse.corepulse_inp   != null;

return [{ json: {
  role: 'assistant', messageType: 'analysis', message: null,
  analysisContext: {
    ...analysisData,
    url_analisada: params.url,
    topico:        params.topic,
    psi_score:   psi.performance_score ?? null,
    psi_lcp:     psi.lcp     ?? null,
    psi_fcp:     psi.fcp     ?? null,
    psi_cls:     psi.cls     ?? null,
    psi_tbt:     psi.tbt     ?? null,
    psi_overall: psi.overall ?? null,
    corepulse_has_metrics: cpHasMetrics,
    corepulse_score:   corepulse.corepulse_score   ?? null,
    corepulse_lcp:     corepulse.corepulse_lcp     ?? null,
    corepulse_fcp:     corepulse.corepulse_fcp     ?? null,
    corepulse_cls:     corepulse.corepulse_cls     ?? null,
    corepulse_inp:     corepulse.corepulse_inp     ?? null,
    corepulse_tbt:     corepulse.corepulse_tbt     ?? null,
    corepulse_grade:   corepulse.corepulse_grade   ?? null,
    user_email_provided: userEmail.length > 0,
    user_email_masked: userEmail ? userEmail.replace(/(.{2}).+(@.+)/, '$1***$2') : null,
    generated_at: new Date().toISOString()
  }
} }];

const result = $input.first()?.json ?? {};
const jobId  = $('Parse Request').first()?.json?.jobId ?? '';
if (jobId) { const s = $getWorkflowStaticData('global'); s[jobId] = result; }
return [{ json: { saved: true } }];

const data    = $('Parse Request').first()?.json ?? {};
const message = data.message ?? '';
const history = data.history ?? [];
const ctx     = data.analysisContext ?? {};
const histText= history.length ? history.map(m=>(m.role==='user'?'Usuário':'Assistente')+': '+m.content).join('\n\n') : '(início da conversa)';
const ctxJSON = JSON.stringify({
  url_analisada: ctx.url_analisada,
  topico: ctx.topico,
  sumario: ctx.sumario,
  correlacoes: ctx.correlacoes,
  gaps_oportunidades: ctx.gaps_oportunidades,
  plano_acao: ctx.plano_acao,
  proximos_passos: ctx.proximos_passos,
  cwv_dados: {
    performance_score: ctx.psi_score,
    lcp: ctx.psi_lcp, fcp: ctx.psi_fcp, cls: ctx.psi_cls, tbt: ctx.psi_tbt,
    campo_geral: ctx.psi_overall,
    corepulse_email_enviado: ctx.cwv_email_enviado
  }
}, null, 2);
return [{ json: { message, histText, ctxJSON, url: ctx.url_analisada??'', topico: ctx.topico??'' } }];

