const result = $input.first()?.json ?? {};
const jobId  = $('Parse Request').first()?.json?.jobId ?? '';
if (jobId) { const s = $getWorkflowStaticData('global'); s[jobId] = result; }
return [{ json: { saved: true } }];

const r = $input.first()?.json ?? {};

// Try to find CWV metrics anywhere in the response shape
const pickFirst = (obj, ...keys) => {
  for (const k of keys) {
    if (obj && obj[k] != null) return obj[k];
  }
  return null;
};

// Some workflows return data inside .data / .result / .metrics
const root = r.data ?? r.result ?? r.metrics ?? r;
const cwv  = root.cwv ?? root.coreWebVitals ?? root.web_vitals ?? root;

return [{ json: {
  corepulse_status:     r.status ?? 'sync',
  corepulse_score:      pickFirst(cwv, 'score', 'performance_score', 'performanceScore'),
  corepulse_lcp:        pickFirst(cwv, 'lcp', 'LCP', 'largest_contentful_paint'),
  corepulse_fcp:        pickFirst(cwv, 'fcp', 'FCP', 'first_contentful_paint'),
  corepulse_cls:        pickFirst(cwv, 'cls', 'CLS', 'cumulative_layout_shift'),
  corepulse_inp:        pickFirst(cwv, 'inp', 'INP', 'interaction_to_next_paint'),
  corepulse_tbt:        pickFirst(cwv, 'tbt', 'TBT', 'total_blocking_time'),
  corepulse_grade:      pickFirst(cwv, 'grade', 'category', 'rating'),
  corepulse_summary:    r.summary ?? r.message ?? root.summary ?? null,
  corepulse_raw:        Object.keys(r).slice(0, 20)
} }];
